SELECT
  1.0 * ((CAST(SUM(CASE WHEN (dash_demo.orders.status <> 'cancelled') THEN dash_demo.order_lines.line_amount END) AS DECIMAL(31,4))) - (CAST(SUM(CASE WHEN (dash_demo.orders.status <> 'cancelled') THEN dash_demo.order_lines.line_cost END) AS DECIMAL(31,4)))) / NULLIF((CAST(SUM(CASE WHEN (dash_demo.orders.status <> 'cancelled') THEN dash_demo.order_lines.line_amount END) AS DECIMAL(31,4))), 0) AS "MarginPct"
FROM dash_demo.order_lines
LEFT JOIN dash_demo.orders ON dash_demo.order_lines.order_id = dash_demo.orders.order_id
LEFT JOIN dash_demo.products ON dash_demo.order_lines.product_id = dash_demo.products.product_id
WHERE dash_demo.orders.order_ts < ${dateTo__next_day}
  AND dash_demo.orders.order_ts >= ${dateFrom}
  AND dash_demo.products.category = ${category}

SELECT
  (CAST(SUM(CASE WHEN (dash_demo.orders.status <> 'cancelled') THEN dash_demo.order_lines.line_amount END) AS DECIMAL(31,4))) - (CAST(SUM(CASE WHEN (dash_demo.orders.status <> 'cancelled') THEN dash_demo.order_lines.line_cost END) AS DECIMAL(31,4))) AS "GrossProfit"
FROM dash_demo.order_lines
LEFT JOIN dash_demo.orders ON dash_demo.order_lines.order_id = dash_demo.orders.order_id
LEFT JOIN dash_demo.products ON dash_demo.order_lines.product_id = dash_demo.products.product_id
WHERE dash_demo.orders.order_ts < ${dateTo__next_day}
  AND dash_demo.orders.order_ts >= ${dateFrom}
  AND dash_demo.products.category = ${category}

